// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint8 lockBlock, bytes32 hash) public {
        // Keep the lock block small so block.number + 1 stays safe, and warp to it after locking.
        lockBlock = uint8(bound(uint256(lockBlock), 1, 100));

        vm.deal(address(this), 1 ether);
        vm.roll(lockBlock);
        c.lockInGuess{value: 1 ether}(hash);

        // Move to exactly the recorded target block: lock block + 1.
        vm.roll(uint256(lockBlock) + 1);

        bool ok = true;
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
